options.css:
#demo-dashboard{--demo-bg:#020910;--demo-cyan:#00e5f3;--demo-line:#07506b;--demo-green:#36c923;--demo-yellow:#ffb800;--demo-red:#ff2925;color:#f5f5f5;background:#020910;position:relative;width:100%;font-family:"Arial Narrow",'Arial Narrow',Arial,sans-serif;line-height:1.2;isolation:isolate}
#demo-dashboard *{box-sizing:border-box}
#demo-dashboard .demo-canvas{display:block;width:100%;height:100%;aspect-ratio:auto;background:#020910;overflow:visible}
#demo-dashboard svg text{font-family:"Arial Narrow",'Arial Narrow',Arial,sans-serif;fill:#f5f5f5;font-weight:400}
#demo-dashboard .demo-title{fill:#f5f5f5;font-size:14.4px;font-weight:700}
#demo-dashboard .demo-node{--node-color:#36c923}
#demo-dashboard .demo-node[data-status="ATTENTION"]{--node-color:#ffb800}
#demo-dashboard .demo-node[data-status="DOWN"]{--node-color:#ff2925}
#demo-dashboard .demo-node[data-status="UNKNOWN"]{--node-color:#8593a1}
#demo-dashboard .demo-node-shape{stroke:var(--node-color);fill:url(#demo-node-fill);stroke-width:1.15;filter:drop-shadow(0 0 6px color-mix(in srgb,var(--node-color) 22%,transparent))}
#demo-dashboard .demo-node .demo-node-port{fill:var(--node-color)}
#demo-dashboard .demo-node .demo-node-state{fill:var(--node-color)}
#demo-dashboard button{font:inherit;color:inherit;cursor:pointer}
#demo-dashboard .demo-hit{width:100%;height:100%;border:0;padding:0;margin:0;display:block;background:transparent;border-radius:7px;color:transparent}
#demo-dashboard .demo-hit:hover{background:rgba(0,229,243,.055)}
#demo-dashboard .demo-hit:focus-visible{outline:2px solid #fff;outline-offset:-3px;background:rgba(0,229,243,.12)}
#demo-dashboard .demo-overlay{position:absolute;inset:0;z-index:3;background:rgba(0,5,12,.78);display:flex;align-items:flex-start;justify-content:center;padding:14% 4% 4%;backdrop-filter:blur(3px)}
#demo-dashboard [hidden]{display:none!important}
#demo-dashboard .demo-dialog{position:relative;background:#04121e;border:1px solid #08768c;border-radius:10px;width:min(480px,100%);padding:26px;box-shadow:0 16px 80px #000;font-size:18px}
#demo-dashboard .demo-dialog h2{font:700 20px "Arial Narrow",Arial,sans-serif;color:#f5f5f5;margin:0 32px 16px 0}
#demo-dashboard .demo-dialog p{font:400 15px/1.45 "Arial Narrow",Arial,sans-serif;margin:12px 0;color:#dce6ed}
#demo-dashboard .demo-close{position:absolute;right:14px;top:13px;background:transparent;border:1px solid #246077;border-radius:4px;font-size:23px;width:32px;height:32px}
#demo-dashboard .demo-dialog small{font-size:12px;color:#9eafbd}
#demo-dashboard .demo-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(prefers-reduced-motion:reduce){#demo-dashboard *{scroll-behavior:auto}}

#demo-dashboard #demo-coverage{font-size:11px!important}#demo-dashboard #demo-app-unknown{font-size:11px!important}#demo-dashboard .demo-dialog-body{white-space:pre-line;overflow-wrap:anywhere}#demo-dashboard .demo-dialog{max-height:72vh;overflow:auto}

/* V14 — animações discretas de status */
@keyframes demo-up-breathe{
  0%,100%{transform:scale(1);filter:drop-shadow(0 0 5px rgba(54,201,35,.18))}
  50%{transform:scale(1.012);filter:drop-shadow(0 0 10px rgba(54,201,35,.34))}
}
@keyframes demo-attention-pulse{
  0%,100%{transform:scale(1);filter:drop-shadow(0 0 5px rgba(255,184,0,.20))}
  50%{transform:scale(1.016);filter:drop-shadow(0 0 12px rgba(255,184,0,.42))}
}
@keyframes demo-down-pulse{
  0%,100%{transform:scale(1);filter:drop-shadow(0 0 5px rgba(255,41,37,.24))}
  50%{transform:scale(1.020);filter:drop-shadow(0 0 14px rgba(255,41,37,.52))}
}
@keyframes demo-state-text-up{
  0%,100%{opacity:.82}
  50%{opacity:1}
}
@keyframes demo-state-text-attention{
  0%,100%{opacity:.78}
  50%{opacity:1}
}
@keyframes demo-state-text-down{
  0%,100%{opacity:.72}
  50%{opacity:1}
}

#demo-dashboard .demo-node-shape{
  transform-box:fill-box;
  transform-origin:center;
  transition:stroke .35s ease, fill .35s ease, filter .35s ease, transform .35s ease;
}
#demo-dashboard .demo-node[data-status="UP"] .demo-node-shape{
  animation:demo-up-breathe 3.8s ease-in-out infinite;
}
#demo-dashboard .demo-node[data-status="ATTENTION"] .demo-node-shape{
  animation:demo-attention-pulse 2.5s ease-in-out infinite;
}
#demo-dashboard .demo-node[data-status="DOWN"] .demo-node-shape{
  animation:demo-down-pulse 1.55s ease-in-out infinite;
}

#demo-dashboard .demo-node .demo-node-state,
#demo-dashboard .demo-node .demo-node-port{
  transition:fill .35s ease, opacity .35s ease;
}
#demo-dashboard .demo-node[data-status="UP"] .demo-node-state{
  animation:demo-state-text-up 3.8s ease-in-out infinite;
}
#demo-dashboard .demo-node[data-status="ATTENTION"] .demo-node-state{
  animation:demo-state-text-attention 2.5s ease-in-out infinite;
}
#demo-dashboard .demo-node[data-status="DOWN"] .demo-node-state{
  animation:demo-state-text-down 1.55s ease-in-out infinite;
}

/* Transições suaves quando o Grafana entrega novos valores */
#demo-dashboard svg text,
#demo-dashboard svg rect,
#demo-dashboard svg path,
#demo-dashboard svg line{
  transition:fill .30s ease, stroke .30s ease, opacity .30s ease, width .30s ease;
}

/* Destaque sutil do status card sem transformar zero em alerta visual */
#demo-dashboard [data-status-card]{
  transition:fill .35s ease, stroke .35s ease, opacity .35s ease;
}

/* Acessibilidade */
@media(prefers-reduced-motion:reduce){
  #demo-dashboard .demo-node-shape,
  #demo-dashboard .demo-node-state,
  #demo-dashboard .demo-node-port,
  #demo-dashboard svg text,
  #demo-dashboard svg rect,
  #demo-dashboard svg path,
  #demo-dashboard svg line,
  #demo-dashboard [data-status-card]{
    animation:none!important;
    transition:none!important;
  }
}

/* V16 — fluxo luminoso mais visível sobre as linhas do mapa */
@keyframes demo-edge-flow{
  from{stroke-dashoffset:0}
  to{stroke-dashoffset:-48}
}
@keyframes demo-edge-glow{
  0%,100%{
    opacity:.34;
    filter:
      drop-shadow(0 0 2px rgba(0,229,243,.28))
      drop-shadow(0 0 5px rgba(0,229,243,.16));
  }
  50%{
    opacity:.82;
    filter:
      drop-shadow(0 0 5px rgba(0,229,243,.58))
      drop-shadow(0 0 10px rgba(0,229,243,.34));
  }
}

#demo-dashboard .demo-edge-flow{
  stroke:#00e5f3;
  stroke-width:1.65;
  stroke-dasharray:11 9;
  stroke-linecap:round;
  fill:none;
  opacity:.52;
  pointer-events:none;
  animation:
    demo-edge-flow 2.05s linear infinite,
    demo-edge-glow 2.35s ease-in-out infinite;
}

/* Ramificações seguem o mesmo fluxo, levemente mais compacto */
#demo-dashboard path[data-edge].demo-edge-flow{
  stroke-dasharray:10 8;
}

/* Linha estrutural permanece contínua sob a animação */
#demo-dashboard line[data-edge]:not(.demo-edge-flow),
#demo-dashboard path[data-edge]:not(.demo-edge-flow){
  opacity:1;
}

/* Pequeno realce das linhas-base para o fluxo ficar legível */
#demo-dashboard line[data-edge]:not(.demo-edge-flow){
  stroke-width:1.6;
}
#demo-dashboard path[data-edge]:not(.demo-edge-flow){
  stroke-width:1.25;
}

@media(prefers-reduced-motion:reduce){
  #demo-dashboard .demo-edge-flow{
    animation:none!important;
    opacity:.22;
    stroke-dashoffset:0;
  }
}

/* V4.2 — popup RECBAN isolado */
#demo-dashboard .demo-dialog-body{white-space:normal;overflow-wrap:anywhere}
#demo-dashboard .demo-rb-head{display:flex;align-items:center;gap:14px;border:1px solid #0b5069;border-radius:8px;background:#03131d;padding:12px 14px;margin:2px 0 10px}
#demo-dashboard .demo-rb-icon{font-size:36px;line-height:1;color:#00dff3}
#demo-dashboard .demo-rb-title{font-size:16px;font-weight:700;min-width:0}
#demo-dashboard .demo-rb-title strong.up{color:#38ca27}
#demo-dashboard .demo-rb-title strong.attention{color:#ffb800}
#demo-dashboard .demo-rb-title strong.down{color:#ff2925}
#demo-dashboard .demo-rb-title strong.unknown{color:#8997a4}
#demo-dashboard .demo-rb-title small{display:block;color:#c4d0da;font-size:12px;font-weight:400;margin-top:5px}
#demo-dashboard .demo-rb-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-bottom:10px}
#demo-dashboard .demo-rb-kpis>div{min-width:0;text-align:center;border:1px solid #18506a;border-radius:7px;background:#03101a;padding:9px 5px}
#demo-dashboard .demo-rb-kpis b{display:block;font-size:23px;color:#f5f5f5}
#demo-dashboard .demo-rb-kpis span{display:block;font-size:9px;font-weight:700;margin-top:3px;color:#cdd8e0;line-height:1.2}
#demo-dashboard .demo-rb-kpis .up b,#demo-dashboard .demo-rb-kpis .up span{color:#38ca27}
#demo-dashboard .demo-rb-kpis .attention b,#demo-dashboard .demo-rb-kpis .attention span{color:#ffb800}
#demo-dashboard .demo-rb-kpis .down b,#demo-dashboard .demo-rb-kpis .down span{color:#ff2925}
#demo-dashboard .demo-rb-latest{display:grid;grid-template-columns:1.5fr .8fr;gap:8px;border:1px solid #0b5069;border-radius:7px;background:#03101a;padding:10px 12px;margin-bottom:10px}
#demo-dashboard .demo-rb-latest span{display:block;color:#aebbc8;font-size:10px;font-weight:700}
#demo-dashboard .demo-rb-latest b{display:block;color:#f5f5f5;font-size:22px;margin:4px 0 2px}
#demo-dashboard .demo-rb-latest small{color:#aebbc8;font-size:10px}
#demo-dashboard .demo-rb-table{border:1px solid #0b5069;border-radius:7px;overflow:hidden;background:#020c14}
#demo-dashboard .demo-rb-row{display:grid;grid-template-columns:1.65fr .9fr 1.05fr .6fr;align-items:center;gap:8px;padding:7px 10px;border-bottom:1px solid #123044;font-size:11px}
#demo-dashboard .demo-rb-row:last-child{border-bottom:0}
#demo-dashboard .demo-rb-row.head{color:#aebbc8;background:#061724;font-size:9px;font-weight:700}
#demo-dashboard .demo-rb-bank small{color:#8395a4}
#demo-dashboard .demo-rb-status{display:flex;align-items:center;gap:6px;font-size:10px;font-weight:800}
#demo-dashboard .demo-rb-status i{display:block;width:8px;height:8px;border-radius:50%;background:currentColor;box-shadow:0 0 6px currentColor}
#demo-dashboard .demo-rb-status.up{color:#38ca27}
#demo-dashboard .demo-rb-status.attention{color:#ffb800}
#demo-dashboard .demo-rb-status.down{color:#ff2925}
#demo-dashboard .demo-rb-status.unknown{color:#8997a4}
#demo-dashboard .demo-rb-row b{text-align:right;color:#f5f5f5;font-size:11px}
#demo-dashboard .demo-rb-row>span:last-child{text-align:right;color:#c8d3dc}
#demo-dashboard .demo-rb-section{color:#00dff3;font-size:11px;font-weight:800;margin:12px 0 5px}
#demo-dashboard .demo-rb-missing{border:1px solid #294656;border-radius:7px;background:#071722;padding:9px 11px;color:#c5d1da;font-size:11px}
#demo-dashboard .demo-rb-missing.has{border-color:#7c5913;background:#171202;color:#ffd36b}
#demo-dashboard .demo-rb-note{margin-top:10px;border:1px solid #294656;border-radius:7px;background:#061622;padding:9px 11px;color:#aebbc8;font-size:10px;line-height:1.35}


