#demo-dashboard .demo-billing-dot.down{color:#ff2925}
#demo-dashboard .demo-billing-dot.partial{color:#7cc7ff}
#demo-dashboard .demo-billing-dot.unknown{color:#8997a4}
#demo-dashboard .demo-billing-row-main b{display:block;font-size:12px;color:#f5f5f5}
