/* Pure adapter: raw Grafana DataFrames -> approved DEMO drawing.
 * Queries and status encodings are traced in mapeamento-consultas.json.
 */
function buildDemoData(panelData, config, clock = Date.now()) {
  const pd = panelData || {};
  const cfg = config || {};
  const inventory = Array.isArray(cfg.services) ? cfg.services : [];
  const settled = pd.state === 'Done' || pd.state === 'Error';
  const frames = Array.isArray(pd.series) ? pd.series : [];
  const values = field => {
    const v = field?.values;
    if (!v || !Number.isInteger(v.length)) return [];
    return Array.from({length:v.length}, (_,i) => typeof v.get === 'function' ? v.get(i) : v[i]);
  };
  const numeric = v => {
    if (v === null || v === undefined || v === '' || typeof v === 'boolean') return null;
    if (typeof v === 'string' && !/^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(v.trim())) return null;
    const n=Number(v);return Number.isFinite(n) ? n : null;
  };
  const millis = v => {
    if (v == null) return null;
    const n = typeof v === 'object' && typeof v.valueOf === 'function' ? v.valueOf() : v;
    const x = typeof n === 'number' ? n : typeof n === 'string' ? Date.parse(n) : NaN;
    return Number.isFinite(x) ? (x >= 1e9 && x < 1e11 ? x*1000 : x) : null;
  };
  const end = millis(pd.timeRange?.to) ?? clock;
  const start = millis(pd.timeRange?.from) ?? end-900000;
  const ageSeconds = numeric(cfg.maxAgeSeconds);
  const maxAge = ageSeconds !== null && ageSeconds > 0 ? ageSeconds*1000 : end-start;
  const errorRefs=new Set();let globalError=false;
  const queryErrors=[];
  const errors=[pd.error,...(Array.isArray(pd.errors)?pd.errors:[])].filter(Boolean);
  for (const e of errors) {
    const ref=e.refId || e.data?.refId;
    if(ref)errorRefs.add(ref);else globalError=true;
    const message=String(e.message || e.data?.message || e.statusText || 'Erro sem detalhes').slice(0,300);
    const detail=`${ref || 'Consulta não identificada'}: ${message}`;
    if(!queryErrors.includes(detail))queryErrors.push(detail);
  }
  // Error can include successful frames from other queries. Block only the
  // failed refId when it is known; never trust cached frames on an unscoped error.
  if(pd.state==='Error' && !errors.length){globalError=true;queryErrors.push('Erro sem consulta identificada. Abra Inspecionar > Consulta para obter a resposta.');}
  const forRef = ref => frames.filter(f => f.refId === ref);
  // Em painel Mixed, um target pode falhar enquanto os demais entregam frames válidos.
  // Erro global sem refId não invalida refs que efetivamente retornaram dados.
  const usable = ref => settled && !errorRefs.has(ref) && (!globalError || forRef(ref).length > 0);
  function classify(v,kind) {
    const n=numeric(v);
    if(kind==='failedStep')return n===0?'UP':n!==null && Number.isInteger(n) && n>0?'DOWN':'UNKNOWN';
    if(kind==='binary')return n===1?'UP':n===0?'DOWN':'UNKNOWN';
    if(kind==='binaryHttp')return n===1||n===200?'UP':n===0?'DOWN':'UNKNOWN';
    if(kind==='endpointSourceMapping')return n===200||n===400||v==='1.30.1'?'UP':[0,403,404].includes(n)?'DOWN':'UNKNOWN';
    return 'UNKNOWN';
  }
  const time = stamp => stamp === null ? '—' : new Date(stamp).toLocaleTimeString('pt-BR',{hour12:false});
  const duration = delta => {
    const seconds=Math.max(0,Math.floor(delta/1000));
    return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(x=>String(x).padStart(2,'0')).join(':');
  };
  const eventList=[];
  function readCheck(check, serviceName, diagnostic=false) {
    const all=[];
    if (!usable(check.refId))return [{
      status:'UNKNOWN',time:null,label:check.label,
      reason:'Consulta pendente ou com erro',history:[]
    }];

    for (const frame of forRef(check.refId)) {
      const fields=Array.isArray(frame.fields)?frame.fields:[];
      const tf=fields.find(f=>f.type==='time'||/^(time|timestamp|@timestamp)$/i.test(f.name));
      const stamps=values(tf);

      for(const field of fields.filter(f=>f!==tf && (f.type==='number'||f.type==='string'))) {
        if(['host','item','item_key'].includes(field.name))continue;

        const vals=values(field);
        const history=vals
          .map((value,i)=>({value,time:millis(stamps[i])}))
          .filter(p=>p.time!==null&&p.time>=start&&p.time<=end)
          .sort((a,b)=>a.time-b.time);

        const latest=history.at(-1);
        const fresh=!!latest && end-latest.time<=maxAge;
        const status=fresh&&!diagnostic?classify(latest.value,check.kind):'UNKNOWN';
        const label=field.labels?.host || field.config?.displayNameFromDS || check.label || field.name;
        const reason=!latest?'Sem amostra com horário válido':
          !fresh?'Amostra anterior ao limite de atualidade':
          latest.value==null?'Última amostra nula':
          status==='UNKNOWN'&&!diagnostic?'Valor sem mapeamento de estado':
          diagnostic?'Informação auxiliar; sem regra UP/DOWN':'';

        all.push({
          status,time:latest?.time??null,fresh,label,
          value:latest?.value,reason,history
        });

        // EVENTOS CRÍTICOS RECENTES
        // Usa somente o histórico da mesma consulta que alimenta o serviço.
        if(!diagnostic && history.length){
          let active=null;
          let previous='UNKNOWN';
          let previousTime=null;

          for(const point of history){
            if(maxAge>0 && previousTime!==null && point.time-previousTime>maxAge){
              if(active){
                eventList.push(active);
                active=null;
              }
              previous='UNKNOWN';
            }

            const state=classify(point.value,check.kind);

            if(state==='DOWN' && previous!=='DOWN'){
              active={
                stamp:point.time,
                time:time(point.time),
                service:serviceName,
                status:'DOWN',
                message:`Falha observada: ${check.label}`,
                end:null
              };
            }

            if(active && previous==='DOWN' && state==='UP'){
              active.end=point.time;
              eventList.push(active);
              active=null;
            }

            if(active && state==='UNKNOWN'){
              eventList.push(active);
              active=null;
            }

            previous=state;
            previousTime=point.time;
          }

          if(active)eventList.push(active);
        }
      }
    }

    const expected=Math.max(0,Number(check.expectedSeries)||0);
    if(expected>all.length){
      const missing=expected-all.length;
      for(let i=0;i<missing;i++){
        all.push({
          status:'UNKNOWN',
          time:null,
          fresh:false,
          label:`${check.label} • série esperada ${all.length+1}/${expected}`,
          value:null,
          reason:'Série esperada não retornada pela query consolidada',
          history:[]
        });
      }
    }

    return all.length?all:[{
      status:'UNKNOWN',time:null,label:check.label,
      reason:'Consulta sem séries',history:[]
    }];
  }
  function aggregate(checks) {
    const counts={UP:0,DOWN:0,ATTENTION:0,UNKNOWN:0};checks.forEach(c=>counts[c.status]++);
    if(!checks.length)return 'UNKNOWN';
    // Prioridade operacional: qualquer falha crítica ativa prevalece.
    if(counts.DOWN)return 'DOWN';
    if(counts.ATTENTION)return 'ATTENTION';
    // Parte da coleta conhecida + parte sem retorno não deve apagar
    // o estado inteiro do serviço. Mantemos ATENÇÃO por cobertura parcial.
    if(counts.UNKNOWN && (counts.UP || counts.DOWN || counts.ATTENTION))return 'ATTENTION';
    if(counts.UNKNOWN)return 'UNKNOWN';
    return 'UP';
  }
  const services={};const updates=[];let sawSample=false;
  for(const service of inventory){
    const checkGroups=(service.checks||[]).map(c=>{
      const items=readCheck(c,service.name);
      const counts={UP:0,DOWN:0,ATTENTION:0,UNKNOWN:0};
      items.forEach(x=>counts[x.status]++);
      const latest=Math.max(0,...items.map(x=>x.time||0));
      const groupStatus=counts.DOWN?'DOWN':
        counts.ATTENTION?'ATTENTION':
        (counts.UNKNOWN&&counts.UP)?'PARTIAL':
        counts.UNKNOWN?'UNKNOWN':'UP';
      return {
        label:c.label,refId:c.refId,items,
        total:items.length,up:counts.UP,down:counts.DOWN,
        attention:counts.ATTENTION,unknown:counts.UNKNOWN,
        status:groupStatus,latest:latest||null
      };
    });
    const checks=checkGroups.flatMap(g=>g.items);
    const diagnostics=(service.diagnostics||[]).flatMap(c=>readCheck(c,service.name,true));
    const all=[...checks,...diagnostics];
    const fresh=all.filter(c=>c.fresh&&c.value!=null);
    const freshDiagnostics=diagnostics.filter(c=>c.fresh&&c.value!=null);
    let state=aggregate(checks);

    // BILLING: uma ausência isolada de coleta NÃO significa degradação funcional.
    // Se existe dado UP e não existe DOWN/ATTENTION comprovado, permanece UP.
    // O sem-dados continua visível no popup como ponto de observação.
    if(service.id==='dae'){
      const hasDown=checks.some(c=>c.status==='DOWN');
      const hasAttention=checks.some(c=>c.status==='ATTENTION');
      const hasUp=checks.some(c=>c.status==='UP');
      const hasUnknown=checks.some(c=>c.status==='UNKNOWN');
      if(!hasDown && !hasAttention && hasUp && hasUnknown)state='UP';
    }
    // Há serviços cuja origem fornece somente informação operacional
    // (ex.: última recepção), sem regra nativa UP/DOWN. Se a coleta existe,
    // mostramos ATENÇÃO em vez de afirmar falsamente que está UP.
    if(!checks.length && freshDiagnostics.length)state='ATTENTION';
    if(fresh.length)sawSample=true;
    const known=checks.filter(c=>c.status!=='UNKNOWN').length;
    const up=checks.filter(c=>c.status==='UP').length;
    const missingCount=checks.length-known;
    const brief=checks.length
      ? (service.id==='dae' && missingCount>0 && state==='UP'
          ? `${up}/${checks.length} verificações UP; ${missingCount} sem dados • sem evidência de falha funcional`
          : `${up}/${checks.length} verificações UP; ${missingCount} sem dados`)
      : (freshDiagnostics.length ? `${freshDiagnostics.length} coleta(s) disponível(is); sem regra UP/DOWN na origem` : 'Sem consulta de status na origem');
    const details=[service.missingReason||brief,...all.slice(0,20).map(c=>`${c.label}: ${c.value==null?'—':String(c.value).slice(0,150)}${c.time?' • '+time(c.time):''}${c.reason?' • '+c.reason:''}`)].join('\n');
    const lastUpdate=Math.max(0,...all.map(c=>c.time||0))||null;
    services[service.id]={
      name:service.name,status:state,functionalStatus:(service.id==='dae'?state:null),message:details,
      checks:checks.length,known,up,missing:missingCount,
      diagnostics:diagnostics.length,lastUpdate,
      checkGroups:checkGroups.map(g=>({
        label:g.label,refId:g.refId,total:g.total,up:g.up,down:g.down,
        attention:g.attention,unknown:g.unknown,status:g.status,latest:g.latest
      })),
      diagnosticItems:diagnostics.map(c=>({
        label:c.label,value:c.value,time:c.time,fresh:c.fresh,reason:c.reason
      })),
      sourceMissing:!checks.length&&!diagnostics.length
    };
    if(fresh.length){const stamp=Math.max(...fresh.map(c=>c.time));updates.push({stamp,time:time(stamp),service:service.name,status:state,message:brief});}
  }
  function countState(entries){
    const out={total:entries.length,healthy:0,attention:0,critical:0,unknown:0,known:0};
    for(const x of entries)out[x.status==='UP'?'healthy':x.status==='DOWN'?'critical':x.status==='ATTENTION'?'attention':'unknown']++;
    out.known=out.total-out.unknown;
    // Blank metrics until at least one service has a known state.
    if(!out.known){out.healthy=null;out.attention=null;out.critical=null;}
    return out;
  }
  const summary=countState(Object.values(services));
  const applications=countState(inventory.filter(s=>s.application).map(s=>services[s.id]));
  function readTerms(ref){
    const map=new Map();let parsedRows=0;let valid=true;
    if(!usable(ref))return {map,valid:false,parsedRows};
    for(const frame of forRef(ref)){
      const fields=frame.fields||[];
      const nameField=fields.find(f=>f.name==='service.name'||f.config?.displayName==='service.name');
      const names=values(nameField);
      const counts=fields.filter(f=>f.type==='number' && f!==nameField && !/^(time|timestamp)$/i.test(f.name));
      if(!counts.length&&fields.length){valid=false;continue;}
      for(const field of counts){
        const countValues=values(field);
        for(let i=0;i<countValues.length;i++){
          const name=names[i]??field.labels?.['service.name']??frame.labels?.['service.name'];
          const count=numeric(countValues[i]);
          if(typeof name!=='string'||!name||count===null||count<0){valid=false;continue;}
          parsedRows++;map.set(name,(map.get(name)||0)+count);
        }
      }
    }
    return {map,valid,parsedRows};
  }
  const failures=readTerms(cfg.apm?.failuresRefId), totals=readTerms(cfg.apm?.totalRefId);
  const impacts=[];
  const apmReady=totals.valid&&totals.parsedRows>0&&failures.valid;
  if(apmReady){
    const failureSum=[...failures.map.values()].reduce((a,b)=>a+b,0);
    const threshold=numeric(cfg.apm?.criticalErrorPct)??5;
    // Missing failure buckets mean zero only for a successful, non-truncated failure query.
    const completeFailureList=failures.map.size<(numeric(cfg.apm?.termLimit)??300);
    for(const [name,total] of totals.map){
      if(!(total>0))continue;
      const failed=failures.map.has(name)?failures.map.get(name):completeFailureList?0:null;
      if(failed===null||failed>total)continue;
      const error=failed/total*100;
      impacts.push({service:name,status:error>=threshold?'DOWN':error>0?'ATTENTION':'UP',impact:failureSum?failed/failureSum*100:0,error,p95:null,failures:failed,total});
    }
    impacts.sort((a,b)=>b.error-a.error||b.failures-a.failures||a.service.localeCompare(b.service));
  }
  const hasData=sawSample||apmReady;
  const minutes=Math.round((end-start)/60000);
  const relative=typeof pd.timeRange?.raw?.from==='string'&&pd.timeRange.raw.from.startsWith('now');
  const rangeLabel=relative&&minutes<=120?`Últimos ${minutes} minutos`:'Período do Grafana';
  return {
    hasData,updatedAt:hasData?time(millis(pd.request?.endTime)??clock):'—',rangeLabel,
    summary,services,applications,
    availability:{value:summary.known?(summary.healthy||0)/summary.known*100:null,known:summary.known,total:summary.total,target:null},
    impacts:impacts.slice(0,5),
    events:(()=>{
      const seen=new Set();
      return eventList
        .sort((a,b)=>b.stamp-a.stamp)
        .filter(e=>{
          const key=`${e.service}|${e.message}|${e.stamp}`;
          if(seen.has(key))return false;
          seen.add(key);
          return true;
        })
        .slice(0,20)
        .map(e=>({
          ...e,
          duration:e.end===null
            ? duration(Math.max(0,end-e.stamp))
            : duration(Math.max(0,e.end-e.stamp))
        }));
    })(), eventsReady:true,
    updates:updates.sort((a,b)=>b.stamp-a.stamp),
    links:{}, apmReady,
    queryDiagnostics:{state:pd.state || 'NotStarted',frames:frames.length,refs:[...new Set(frames.map(f=>f.refId).filter(Boolean))],errors:queryErrors,globalError}
  };
}


(() => {
  const root=htmlNode.querySelector('#demo-dashboard');
  if(!root?.demo)return;

  // O refresh continua 100% controlado pelo Grafana.
  // Durante Loading/Streaming/NotStarted, preservamos o último estado
  // renderizado em vez de converter temporariamente tudo para SEM DADOS.
  const panelData=htmlGraphics.data||{};
  const state=panelData.state||'NotStarted';
  const settled=state==='Done'||state==='Error';

  if(!settled){
    root.dataset.refreshing='true';
    return;
  }

  root.dataset.refreshing='false';
  const next=buildDemoData(panelData,htmlGraphics.customProperties);
  root.demo.update(next);
  // O bridge RECBAN é outro painel/consulta. Assim Problems nunca participa
  // do mesmo lote Zabbix das 14 queries do mapa.
  if(globalThis.__demoRecbanProblems){
    root.demo.applyRecban?.(globalThis.__demoRecbanProblems);
  }
  if(globalThis.__demoBillingApm){
    root.demo.applyBillingApm?.(globalThis.__demoBillingApm);
  }
})();

(() => {
  const pd = htmlGraphics.data || {};
  const state = pd.state || 'NotStarted';
  if(state!=='Done' && state!=='Error')return;

  const frames = Array.isArray(pd.series)?pd.series:[];
  const errors=[pd.error,...(Array.isArray(pd.errors)?pd.errors:[])].filter(Boolean);
  const failed = errors.length>0 || (state==='Error' && !frames.length);

  const banks=[
    {code:'001',name:'Banco do Brasil'},
    {code:'033',name:'Santander'},
    {code:'037',name:'Demo Bank'},
    {code:'104',name:'Caixa'},
    {code:'237',name:'Bradesco'},
    {code:'341',name:'Itaú'},
    {code:'756',name:'Sicoob'}
  ];

  const arr=v=>{
    if(v==null)return[];
    if(Array.isArray(v))return v;
    if(typeof v.toArray==='function')return v.toArray();
    const out=[];for(let i=0;i<(v.length||0);i++)out.push(v.get?v.get(i):v[i]);return out;
  };
  const bankFromText=value=>{
    const s=String(value||'').toUpperCase();
    const rules=[
      ['001',['001','BANK A']],
      ['033',['033','BANK B']],
      ['037',['037','DEMO BANK','DEMO BANK','BANK H']],
      ['104',['104','CAIXA']],
      ['237',['237','BANK D']],
      ['341',['341','BANK E','BANK E']],
      ['756',['756','BANK F']]
    ];
    for(const [code,terms] of rules)if(terms.some(t=>s.includes(t)))return code;
    return '';
  };
  const severity=v=>{
    const n=Number(v);
    if(Number.isFinite(n))return ['NOT CLASSIFIED','INFORMATION','WARNING','AVERAGE','HIGH','DISASTER'][n]||String(v);
    const s=String(v||'').toUpperCase();
    if(s.includes('DISASTER'))return 'DISASTER';
    if(s.includes('HIGH')||s.includes('ALTA'))return 'HIGH';
    return s;
  };
  const pick=(o,names)=>{
    for(const n of names){
      if(o[n]!==undefined&&o[n]!==null&&o[n]!=='')return o[n];
      const k=Object.keys(o).find(k=>k.toLowerCase()===String(n).toLowerCase());
      if(k&&o[k]!==undefined&&o[k]!==null&&o[k]!=='')return o[k];
    }
    return null;
  };

  const ranks={},problems={};
  if(!failed){
    for(const frame of frames){
      const fields=Array.isArray(frame.fields)?frame.fields:[];
      const cols=fields.map(f=>({name:f.name||'',values:arr(f.values),labels:f.labels||{}}));
      const count=Math.max(0,...cols.map(c=>c.values.length));
      for(let i=0;i<count;i++){
        const row={_frameName:frame.name||frame.schema?.name||''};
        cols.forEach(c=>{
          row[c.name]=c.values[i];
          Object.entries(c.labels||{}).forEach(([k,v])=>{if(row[k]===undefined)row[k]=v;});
          const x=c.values[i];
          if(x&&typeof x==='object'&&!Array.isArray(x))Object.entries(x).forEach(([k,v])=>{if(row[k]===undefined)row[k]=v;});
        });
        const desc=String(pick(row,['Problem','problem','Name','name','Description','description','Trigger','trigger','problem_name','event_name','Event name'])||row._frameName||'');
        if(!desc.toLowerCase().includes('recep'))continue;
        const code=bankFromText(desc);if(!code)continue;
        const sev=severity(pick(row,['Severity','severity','Priority','priority','Problem severity','problem_severity','trigger_priority','Trigger severity']));
        const rank=sev==='DISASTER'?5:sev==='HIGH'?4:0;
        if(rank>(ranks[code]||0)){ranks[code]=rank;problems[code]=desc;}
      }
    }
  }

  const payload={
    usable:!failed,
    updatedAt:Date.now(),
    banks:banks.map(b=>{
      if(failed)return {...b,status:'UNKNOWN',problem:''};
      const r=ranks[b.code]||0;
      return {...b,status:r>=5?'DOWN':r===4?'ATTENTION':'UP',problem:problems[b.code]||''};
    })
  };

  globalThis.__demoRecbanProblems=payload;
  try{
    globalThis.dispatchEvent(new CustomEvent('demo-payment-intake-status',{detail:payload}));
  }catch(_){}
})();

(() => {
  const pd=htmlGraphics.data||{};
  const state=pd.state||'NotStarted';
  if(state!=='Done'&&state!=='Error')return;

  const frames=Array.isArray(pd.series)?pd.series:[];
  const errors=[pd.error,...(Array.isArray(pd.errors)?pd.errors:[])].filter(Boolean);
  const failed=errors.length>0 || (state==='Error'&&!frames.length);

  const names=['dae','billing-service','billing-pix-api'];
  const M={};names.forEach(s=>M[s]={name:s,total:null,fail:null,latencyMs:null});

  const arr=v=>{
    if(v==null)return[];
    if(Array.isArray(v))return v;
    if(typeof v.toArray==='function')return v.toArray();
    if(v.buffer)return Array.from(v.buffer);
    const out=[];for(let i=0;i<(v.length||0);i++)out.push(v.get?v.get(i):v[i]);return out;
  };
  const num=v=>{const n=Number(v);return Number.isFinite(n)?n:null};
  const svc=v=>{
    const s=String(v??'').trim().toLowerCase();
    return names.includes(s)?s:null;
  };
  const byRef=ref=>frames.filter(f=>String(f?.refId||'')===ref);

  if(!failed){
    for(const f of byRef('TX_TOTAL')){
      const fs=f.fields||[];
      const nf=fs.find(x=>String(x?.name||'')==='service.name');
      const cf=fs.find(x=>String(x?.name||'').toLowerCase().includes('count'));
      const af=fs.find(x=>{
        const n=String(x?.name||'').toLowerCase();
        return n.includes('average')||n.includes('duration');
      });
      const ns=arr(nf?.values),cs=arr(cf?.values),av=arr(af?.values);
      for(let i=0;i<ns.length;i++){
        const s=svc(ns[i]);if(!s)continue;
        const c=num(cs[i]),a=num(av[i]);
        if(c!==null)M[s].total=c;
        if(a!==null)M[s].latencyMs=a/1000;
      }
    }

    for(const f of byRef('TX_FAIL')){
      const fs=f.fields||[];
      const nf=fs.find(x=>String(x?.name||'')==='service.name');
      const cf=fs.find(x=>String(x?.name||'').toLowerCase().includes('count'));
      const ns=arr(nf?.values),cs=arr(cf?.values);
      for(let i=0;i<ns.length;i++){
        const s=svc(ns[i]);if(!s)continue;
        const c=num(cs[i]);if(c!==null)M[s].fail=c;
      }
    }
  }

  const services=names.map(name=>{
    const x=M[name];
    const rate=x.total!==null&&x.total>0 ? ((x.fail??0)/x.total*100) : null;
    const severity=rate===null?'UNKNOWN':rate>=5?'CRITICAL':rate>=1?'WARNING':'OK';
    const severityClass=severity==='CRITICAL'?'crit':severity==='WARNING'?'warn':severity==='OK'?'ok':'na';
    const label=severity==='CRITICAL'?'CRÍTICO':severity==='WARNING'?'ATENÇÃO':severity==='OK'?'OK':'SEM DADOS';
    return {...x,failureRate:rate,severity,severityClass,label};
  });

  const known=services.filter(x=>x.failureRate!==null);
  const worst=known.slice().sort((a,b)=>(b.failureRate??-1)-(a.failureRate??-1))[0]||null;
  const severity=failed||!known.length?'UNKNOWN':
    known.some(x=>x.severity==='CRITICAL')?'CRITICAL':
    known.some(x=>x.severity==='WARNING')?'WARNING':'OK';

  const payload={
    usable:!failed,
    updatedAt:Date.now(),
    received:known.length,
    severity,
    severityClass:severity==='CRITICAL'?'crit':severity==='WARNING'?'warn':severity==='OK'?'ok':'na',
    label:severity==='CRITICAL'?'CRÍTICA':severity==='WARNING'?'ATENÇÃO':severity==='OK'?'NORMAL':'SEM DADOS',
    worstRate:worst?.failureRate??0,
    worstService:worst?.name??null,
    services
  };

  globalThis.__demoBillingApm=payload;
  try{
    globalThis.dispatchEvent(new CustomEvent('demo-billing-apm',{detail:payload}));
  }catch(_){}
})();
